const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();

const webhookBody = $('Webhook - POST /holidays').first().json.body || {};
const action = (webhookBody.action || 'LIST').toUpperCase().trim();

if ((action === 'ADD' || action === 'DELETE') && callerRole !== 'ADMIN') {
  return [{
    json: {
      valid: false,
      statusCode: 403,
      error: "Forbidden: Administrator access required to modify holidays."
    }
  }];
}

return [{
  json: {
    valid: true,
    callerId,
    callerRole,
    action,
    name: (webhookBody.name || '').trim(),
    date: (webhookBody.date || '').trim(),
    day: (webhookBody.day || '').trim(),
    type: (webhookBody.type || 'PUBLIC').trim().toUpperCase(),
    description: (webhookBody.description || '').trim(),
    isOfficeClosed: webhookBody.isOfficeClosed !== false,
    holidayId: (webhookBody.holidayId || '').trim()
  }
}];

const prev = $('Code - Parse Claims').first().json || {};
const rawItems = $input.all().map(i => i.json);
const validHolidays = rawItems.filter(h => h && h.id && h.name && h.date);

if (prev.action === 'ADD') {
  return [{
    json: {
      success: true,
      statusCode: 201,
      message: "Holiday added successfully.",
      holiday: validHolidays[0] || rawItems[0] || null
    }
  }];
} else if (prev.action === 'DELETE') {
  return [{
    json: {
      success: true,
      statusCode: 200,
      message: "Holiday deleted successfully."
    }
  }];
} else {
  return [{
    json: {
      success: true,
      statusCode: 200,
      total: validHolidays.length,
      holidays: validHolidays
    }
  }];
}

